import Card from "@marko-ui/shadcn/ui/card/card.marko";
import CardHeader from "@marko-ui/shadcn/ui/card/header.marko";
import CardContent from "@marko-ui/shadcn/ui/card/content.marko";
import Tabs from "@marko-ui/shadcn/ui/tabs/tabs.marko";
import CollapsibleFileTreeItem, {
  type FileTreeItem,
} from "./lib/collapsible-file-tree-item.marko";

static const fileTree: FileTreeItem[] = [
  {
    name: "components",
    items: [
      {
        name: "ui",
        items: [
          { name: "button.marko" },
          { name: "card.marko" },
          { name: "dialog.marko" },
          { name: "input.marko" },
          { name: "select.marko" },
          { name: "table.marko" },
        ],
      },
      { name: "login-form.marko" },
      { name: "register-form.marko" },
    ],
  },
  {
    name: "lib",
    items: [
      { name: "utils.ts" },
      { name: "cn.ts" },
      { name: "api.ts" },
    ],
  },
  {
    name: "hooks",
    items: [
      { name: "use-media-query.ts" },
      { name: "use-debounce.ts" },
      { name: "use-local-storage.ts" },
    ],
  },
  {
    name: "types",
    items: [{ name: "index.d.ts" }, { name: "api.d.ts" }],
  },
  {
    name: "public",
    items: [
      { name: "favicon.ico" },
      { name: "logo.svg" },
      { name: "images" },
    ],
  },
  { name: "app.marko" },
  { name: "layout.marko" },
  { name: "globals.css" },
  { name: "package.json" },
  { name: "tsconfig.json" },
  { name: "README.md" },
  { name: ".gitignore" },
];

<Card class="mx-auto w-full max-w-[16rem] gap-2" size="sm">
  <CardHeader>

    <Tabs class="w-full">
      <@trigger value="explorer">Explorer</@trigger>
      <@trigger value="settings">Outline</@trigger>
      <@panel value="explorer"/>
      <@panel value="settings"/>
    </Tabs>
  </CardHeader>
  <CardContent>
    <div class="flex flex-col gap-1">
      <for|item| of=fileTree>
        <CollapsibleFileTreeItem item=item/>
      </for>
    </div>
  </CardContent>
</Card>
